const issueCases = $('Read Form Issue Cases1').all().map(i => i.json || {});
const params = $('Set Weekly API Params').first().json || {};

return [{
  json: {
    issue_cases: issueCases,
    week_days: Number(params.week_days ?? 7),
    issue_case_count: issueCases.length,
  },
}];

const r = $input.first().json || {};

return [{
  json: {
    report_type: r.report_type,
    report_generated_at: r.report_generated_at,
    week_window_label: r.week_window_label,
    week_days: r.week_days,
    summary: r.summary,
    operative_stats: r.operative_stats,
    week_issues: r.week_issues,
    still_open_carry: r.still_open_carry,
    missing_ojs: r.missing_ojs || [],
    pdf_filename: `weekly-form-performance-${new Date().toISOString().slice(0, 10)}.pdf`,
  },
}];

function esc(t){return String(t??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function statCard(value, label, accent) {
  const color = accent ? 'color:' + accent + ';' : '';
  return '<td style="background:#f7fafb;border:1px solid #dce3e8;border-radius:8px;padding:14px;text-align:center;width:22%;">'
    + '<div style="font-size:22px;font-weight:700;' + color + '">' + esc(value) + '</div>'
    + '<div style="font-size:10px;color:#56616b;text-transform:uppercase;">' + esc(label) + '</div></td>';
}
const built = $('Build Weekly PDF Payload').first().json || {};
const pdf = $input.first().binary?.report_pdf;
if (!pdf) throw new Error('Weekly performance PDF not returned by API');
const s = built.summary || {};
const reportDate = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London' }).replace(',', '');
const logo = 'https://jeffway.co.uk/wp-content/uploads/2025/05/jeffway-group-1.svg';
const sheetUrl = 'https://docs.google.com/spreadsheets/d/1mkklLpvi8klaN4Zo4D_cBrb95PGQ4NbUvtTAvLI4CII/edit';
const statsRow = '<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"><tr>'
  + statCard(s.issues_in_week, 'Raised this week', '#145c63')
  + '<td width="8"></td>'
  + statCard(s.resolved_in_week, 'Resolved', '#2e7d32')
  + '<td width="8"></td>'
  + statCard(s.still_open_in_week, 'Still open (week)', '#c0392b')
  + '<td width="8"></td>'
  + statCard(s.older_still_open, 'Older still open', '#56616b')
  + '</tr></table>';
const html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="margin:0;padding:0;font-family:Arial,Helvetica,sans-serif;background:#f4f4f4;">',
  '<table width="100%" style="background:#f4f4f4;padding:20px;"><tr><td align="center">',
  '<table width="640" style="background:#fff;border-radius:8px;overflow:hidden;">',
  '<tr><td style="background:#145c63;padding:20px;text-align:center;"><img src="' + logo + '" style="max-width:160px;" alt="Jeffway Group"></td></tr>',
  '<tr><td style="padding:24px 24px 8px;"><h2 style="margin:0;color:#145c63;">Weekly Form Quality Performance</h2>',
  '<p style="color:#56616b;font-size:13px;margin:8px 0 0;">Week: <strong style="color:#17212b;">' + esc(built.week_window_label) + '</strong> · Generated ' + esc(reportDate) + ' (Europe/London)</p></td></tr>',
  '<tr><td style="padding:8px 24px 8px;"><p style="color:#444;font-size:14px;margin:0 0 16px;">The weekly performance report is attached as a PDF. Summary:</p>',
  statsRow,
  '</td></tr>',
  '<tr><td style="padding:0 24px 24px;text-align:center;">',
  '<a href="' + sheetUrl + '" style="display:inline-block;padding:10px 18px;background:#145c63;color:#fff;text-decoration:none;border-radius:4px;font-size:13px;">Open Form Issue Cases sheet</a>',
  '</td></tr>',
  '<tr><td style="background:#f7fafb;padding:16px;text-align:center;font-size:11px;color:#56616b;">Jeffway Group · Stage 6 weekly form performance automation</td></tr>',
  '</table></td></tr></table></body></html>',
].join('');
return [{ json: { email_subject: 'Weekly Form Performance — ' + built.week_window_label, email_html: html, pdf_filename: built.pdf_filename }, binary: { report_pdf: { ...pdf, fileName: built.pdf_filename } } }];
